class Section:
    def __init__(self, name):
        self.name = name

    def __enter__(self):
        print(f"start: {self.name}")
        return self

    def __exit__(self, exc_type, exc, tb):
        status = "ok" if exc_type is None else exc_type.__name__
        print(f"end: {self.name} ({status})")
        return False


with Section("outer"):
    with Section("inner") as s:
        print(f"inside {s.name}")

try:
    with Section("risky"):
        raise ValueError("bad value")
except ValueError as e:
    print(f"caught: {e}")

