practice.solution:
class Tag:
    def __init__(self, name):
        self.name = name

    def __enter__(self):
        print(f"<{self.name}>")
        return self

    def __exit__(self, exc_type, exc, tb):
        print(f"</{self.name}>")
        return False


line = input()
with Tag("div"):
    with Tag("p") as t:
        print(f"{t.name}: {line}")

try:
    with Tag("b"):
        raise ValueError("oops")
except ValueError as e:
    print(f"caught: {e}")

