from contextlib import contextmanager, suppress


@contextmanager
def tag(name):
    print(f"<{name}>")
    try:
        yield name
    finally:
        print(f"</{name}>")


with tag("ul"):
    with tag("li") as current:
        print(f"inside {current}")

try:
    with tag("em"):
        raise ValueError("bad")
except ValueError:
    print("caught ValueError")

prices = {"apple": 3, "pear": 2}
for fruit in ["apple", "plum", "pear"]:
    with suppress(KeyError):
        print(f"{fruit}: {prices[fruit]}")
print("done")
